import {state} from '../../core/state.js?v=2a0a4e3abb7b';
import {api,projectQuery,exportFile} from '../../core/api.js?v=2a0a4e3abb7b';
import {T,esc,icon,heading,panel,select,empty,date,toast} from '../../core/ui.js?v=2a0a4e3abb7b';
let formats=[],history=[];
export async function load(){if(state.workspace.project.can_manage){const r=await api('studio/exports'+projectQuery());formats=r.formats;history=r.history;}}
export function render(){if(!state.workspace.project.can_manage)return empty(T('Dành cho quản lý dự án','Project managers only'),T('Liên hệ quản lý để xuất dữ liệu.','Ask a project manager to export data.'));return heading(T('Xuất dữ liệu','Export data'),T('Tải bình luận và nhãn đã gán về máy.','Download comments and their annotations.'))+`<div class="simple-export">${panel(T('Tải kết quả','Download results'),`<form data-submit="exports:download">${select('format',T('Định dạng tệp','File format'),formats.filter(f=>['csv_sentence','json_sentence'].includes(f.id)).map(f=>[f.id,f.id==='csv_sentence'?'CSV':'JSON']),'csv_sentence')}${select('scope',T('Dữ liệu cần tải','Records to download'),[['human',T('Bình luận đã được người gán nhãn','Human-reviewed comments')],['gold',T('Bình luận đã chốt nhãn','Agreed / adjudicated comments')],['all',T('Tất cả, gồm bình luận chưa gán nhãn','All, including unlabelled comments')]],'human')}${select('source',T('Nguồn dữ liệu','Data source'),[['',T('Toàn dự án','Entire project')],...state.workspace.sources.map(s=>[s.id,s.name])],'')}<details class="annotation-extra"><summary>${T('Định dạng nâng cao','Advanced formats')}</summary>${select('advanced_format',T('Thay thế định dạng tệp phía trên','Override the file format above'),[['',T('Dùng CSV / JSON đã chọn','Use selected CSV / JSON')],...formats.filter(f=>!['csv_sentence','json_sentence'].includes(f.id)).map(f=>[f.id,f.name+' · .'+f.extension])],'')}</details><div class="form-error-slot" aria-live="polite"></div><button class="btn primary" type="submit">${icon('download',16)}${T('Tải xuống','Download')}</button></form>`)}<details class="annotation-extra"><summary>${T('Lịch sử tải xuống','Download history')}</summary>${history.length?`<div class="table-wrap"><table><thead><tr><th>${T('Định dạng','Format')}</th><th>${T('Số mẫu','Records')}</th><th>${T('Thời điểm','Created')}</th></tr></thead><tbody>${history.map(h=>`<tr><td>${esc(h.format)}</td><td>${h.rows}</td><td>${date(h.created_at)}</td></tr>`).join('')}</tbody></table></div>`:`<p>${T('Chưa có bản xuất.','No exports yet.')}</p>`}</details></div>`;}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f));const selected=v.advanced_format||v.format;const format=formats.find(x=>x.id===selected);if(!format)throw new Error(T('Chọn định dạng tệp.','Choose a file format.'));await exportFile('studio/export'+projectQuery()+`&format=${encodeURIComponent(selected)}&scope=${encodeURIComponent(v.scope)}${v.source?'&source='+encodeURIComponent(v.source):''}`,`annotaflow-${state.workspace.project.id}-${selected}.${format.extension}`);toast(T('Đã tải bản xuất.','Export downloaded.'));}
